    java.util.List<java.util.Set<String>> substrSets = new java.util.ArrayList<>();
    for (String s : strings) {
        java.util.Set<String> set = new java.util.HashSet<>();
        int len = s.length();
        for (int i = 0; i < len; i++) {
            for (int j = i + 1; j <= len; j++) {
                set.add(s.substring(i, j));
            }
        }
        substrSets.add(set);
    }

