    int[] totalTime = {0};
    dfs(0, graph, visited, hasApple, totalTime);
    return totalTime[0];
}

private boolean dfs(int node, List<Integer>[] graph, boolean[] visited, boolean[] hasApple, int[] totalTime) {
    visited[node] = true;
    boolean foundAppleInSubtree = hasApple[node];

    for (int neighbor : graph[node]) {
        if (!visited[neighbor]) {
            boolean childHasApple = dfs(neighbor, graph, visited, hasApple, totalTime);
            if (childHasApple) {
                // Need to travel to child and back
                totalTime[0] += 2;
                foundAppleInSubtree = true;
            }
        }
    }
    return foundAppleInSubtree;
}

